from marshmallow.utils import ensure_text_type
from marshmallow.utils import is_generator
from marshmallow.utils import is_iterable_but_not_string
from marshmallow.orderedset import OrderedSet
from marshmallow.fields import Field
from marshmallow.exceptions import ValidationError
from marshmallow.decorators import validates
from marshmallow.decorators import set_hook
from hypothesis import given, settings
import hypothesis.strategies as st


@settings(max_examples=300, deadline=None)
@given(val=st.text())
def test_ensure_text_type_never_crashes(val):
    assert isinstance(ensure_text_type(val), str)
    assert ensure_text_type(val.encode("utf-8")) == val


@settings(max_examples=300, deadline=None)
@given(obj=st.one_of(st.text(), st.integers(), st.lists(st.integers()), st.dictionaries(st.text(), st.integers()), st.none(), st.booleans()))
