    assert isinstance(is_generator(obj), bool)


@settings(max_examples=300, deadline=None)
@given(obj=st.one_of(st.text(), st.binary(), st.integers(), st.lists(st.text()), st.tuples(st.integers()), st.dictionaries(st.text(), st.text()), st.none()))
def test_is_iterable_but_not_string_never_crashes(obj):
    assert isinstance(is_iterable_but_not_string(obj), bool)


@settings(max_examples=300, deadline=None)
@given(key=st.one_of(st.text(), st.integers(min_value=-10**18, max_value=10**18)))
def test_OrderedSet_add_never_crashes(key):
    s = OrderedSet()
    s.add(key)


@settings(max_examples=300, deadline=None)
@given(key=st.one_of(st.text(), st.integers(min_value=-10**18, max_value=10**18)))
def test_OrderedSet_discard_never_crashes(key):
    s = OrderedSet()
    s.discard(key)


@settings(max_examples=300, deadline=None)
@given(key=st.text())
def test_Field_make_error_never_crashes(key):
    f = Field()
    f.make_error(key)


@settings(max_examples=300, deadline=None)
@given(msg=st.one_of(st.text(), st.lists(st.text()), st.dictionaries(st.text(), st.lists(st.text()))))
def test_ValidationError_normalized_messages_never_crashes(msg):
    e = ValidationError(msg)
    e.normalized_messages()


@settings(max_examples=300, deadline=None)
@given(names=st.lists(st.text()))
def test_validates_never_crashes(names):
    validates(*names)
